    """较大负数同样应被拒绝，而不是无限递归或返回错误值。"""
    with pytest.raises((ValueError, RecursionError)):
        factorial(-10)


def test_factorial_recurrence_relation():
    """数学定律：n! = n * (n-1)!，对 n>=1 成立。"""
    for n in range(1, 8):
        assert factorial(n) == n * factorial(n - 1)


def test_factorial_ratio_relation():
    """数学定律：n! / (n-1)! == n，对 n>=1 成立。"""
    for n in range(1, 8):
        assert factorial(n) // factorial(n - 1) == n


def test_factorial_monotonic_increasing():
